#include <stdio.h>



int main(void)
{
    int tail[]={1,2,5},x=4,lo=0,hi=3;
    while(lo<hi){int mid=lo+(hi-lo)/2;
        if(tail[mid]<x){lo=mid+1;}else{hi=mid;}}
    printf("%d\n",lo);
    return 0;
}

